INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7687890, 1259292, 39144, '<td valign="top">Definitely my favorite of this challenge. I love how the light shines right through the tree tops to illuminate the grass and flowers below. Nice work!</td>', 'Definitely my favorite of this challenge. I love how the light shines right through the tree tops to illuminate the grass and flowers below. Nice work!', '2021-02-24 01:43:49.000000', NULL, 1),
(7687894, 1259251, 4008, '<td valign="top">Funny. LOL.</td>', 'Funny. LOL.', '2021-02-24 04:07:46.000000', NULL, 1),
(7687896, 1259049, 4008, '<td valign="top">Great depth and detail. I like it how you used both a foreground and background point of interest. A pity the clouds were not cooperating more.</td>', 'Great depth and detail. I like it how you used both a foreground and background point of interest. A pity the clouds were not cooperating more.', '2021-02-24 04:14:00.000000', NULL, 1),
(7687897, 1259350, 4008, '<td valign="top">This has a sixties feels to it with the fading colours of old printed pictures. Maybe a bit too much.</td>', 'This has a sixties feels to it with the fading colours of old printed pictures. Maybe a bit too much.', '2021-02-24 04:16:01.000000', NULL, 1),
(7687898, 1259294, 4008, '<td valign="top">Nice road, great trees. It has a lovely warmth to it. I would have taken a few steps forward to get rid of the white poles on the left (or clone them out afterwards), they are so distracting.</td>', 'Nice road, great trees. It has a lovely warmth to it. I would have taken a few steps forward to get rid of the white poles on the left (or clone them out afterwards), they are so distracting.', '2021-02-24 04:18:58.000000', NULL, 1),
(7687899, 1259349, 4008, '<td valign="top">Great. Different. Makes me stop, explore and think. Lovely light as well.</td>', 'Great. Different. Makes me stop, explore and think. Lovely light as well.', '2021-02-24 04:21:09.000000', NULL, 1),
(7687900, 1259196, 4008, '<td valign="top">Lovely atmosphere and composition. It needs a slight clockwise rotation.</td>', 'Lovely atmosphere and composition. It needs a slight clockwise rotation.', '2021-02-24 04:24:40.000000', NULL, 1),
(7687902, 1259384, 4008, '<td valign="top">I like it how you have included the sky to this scene, but I think by emphasising the sky colour you have added a strong blue cast to the total image (if you use photoshop levels eyedropper on the white building you get the natural colours).  There is also quite some distortion: the white building is straight but then the lines both on the left and right side falls inwards towards to top, especially visible in the two silos and the red barn on the right. Is it caused by the wide angle lens or by by post processing? It could be corrected with a perspective correction.</td>', 'I like it how you have included the sky to this scene, but I think by emphasising the sky colour you have added a strong blue cast to the total image (if you use photoshop levels eyedropper on the white building you get the natural colours).  There is also quite some distortion: the white building is straight but then the lines both on the left and right side falls inwards towards to top, especially visible in the two silos and the red barn on the right. Is it caused by the wide angle lens or by by post processing? It could be corrected with a perspective correction.', '2021-02-24 04:31:55.000000', NULL, 1),
(7687903, 1259386, 4008, '<td valign="top">Wow, very different and attractive scene. Nice depth as well. I am sure this will do well since it has the appeal factor. Personally the post processing is a bit too strong for me, it causes a purple colour cast across the whole image, even the grass and the white chair.</td>', 'Wow, very different and attractive scene. Nice depth as well. I am sure this will do well since it has the appeal factor. Personally the post processing is a bit too strong for me, it causes a purple colour cast across the whole image, even the grass and the white chair.', '2021-02-24 04:36:19.000000', NULL, 1),
(7687904, 1259339, 4008, '<td valign="top">I love infrared and it works well here.</td>', 'I love infrared and it works well here.', '2021-02-24 04:37:22.000000', NULL, 1),
(7687905, 1259353, 4008, '<td valign="top">Gorgeous. I love the low light and how it makes the yellow trees jump out. The three layers (warm foreground, then low clouds, then mountains) work great together.</td>', 'Gorgeous. I love the low light and how it makes the yellow trees jump out. The three layers (warm foreground, then low clouds, then mountains) work great together.', '2021-02-24 04:39:00.000000', NULL, 1),
(7687906, 1259389, 4008, '<td valign="top">I like the four layers in this image. For me the foreground layer is a bit too much, I would crop away part of it to bring it more in balance with the size of the other layers.</td>', 'I like the four layers in this image. For me the foreground layer is a bit too much, I would crop away part of it to bring it more in balance with the size of the other layers.', '2021-02-24 04:44:21.000000', NULL, 1),
(7687908, 1259256, 4008, '<td valign="top">Great leading line of the fence up to the farm. Nice scene. I can''t see the separation between the roof and background but does not matter to me since the weather is not fully bright so it matches the atmosphere. There is a purple colour cast caused by the vignette.</td>', 'Great leading line of the fence up to the farm. Nice scene. I can''t see the separation between the roof and background but does not matter to me since the weather is not fully bright so it matches the atmosphere. There is a purple colour cast caused by the vignette.', '2021-02-24 04:49:22.000000', NULL, 1),
(7687920, 1258907, 6803, '<td valign="top">https://www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1258907#</td>', 'https://www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1258907#', '2021-02-24 07:59:28.000000', NULL, 1),
(7687990, 1259326, 18197, '<td valign="top">For me, the texture diminishes an otherwise high scoring photo. I understand it''s a matter of what appeals and some will believe the texture helps. I just disagree.</td>', 'For me, the texture diminishes an otherwise high scoring photo. I understand it''s a matter of what appeals and some will believe the texture helps. I just disagree.', '2021-02-24 19:40:02.000000', NULL, 1),
(7688008, 1259314, 65234, '<td valign="top">I like the muted palette and the white vignette. Feels peaceful.</td>', 'I like the muted palette and the white vignette. Feels peaceful.', '2021-02-25 09:39:04.000000', NULL, 1),
(7688010, 1259353, 65234, '<td valign="top">Gorgeous view! Literally rolling countryside. The mist and the mountains make a nice backdrop for the farmland.</td>', 'Gorgeous view! Literally rolling countryside. The mist and the mountains make a nice backdrop for the farmland.', '2021-02-25 09:40:45.000000', NULL, 1),
(7688011, 1259336, 65234, '<td valign="top">Nice perspective (drone?).</td>', 'Nice perspective (drone?).', '2021-02-25 09:41:12.000000', NULL, 1),
(7688012, 1259358, 65234, '<td valign="top">I like the pop of red and the bit of color in the sky. Nice old barn.</td>', 'I like the pop of red and the bit of color in the sky. Nice old barn.', '2021-02-25 09:41:46.000000', NULL, 1),
(7688013, 1259339, 65234, '<td valign="top">Very bright but strangely silent. That sky is so very dramatic. IR?</td>', 'Very bright but strangely silent. That sky is so very dramatic. IR?', '2021-02-25 09:43:27.000000', NULL, 1),
(7688014, 1259386, 65234, '<td valign="top">Oh, that must smell heavenly. Beautifully serene scene and I like the bit of purple in the sky echoing the purple lavender.</td>', 'Oh, that must smell heavenly. Beautifully serene scene and I like the bit of purple in the sky echoing the purple lavender.', '2021-02-25 09:45:10.000000', NULL, 1),
